import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import ExtensionPermissionGrid from 'flarum/admin/components/ExtensionPermissionGrid';
import Form from 'flarum/common/components/Form';
import ItemList from 'flarum/common/utils/ItemList';

/**
 * Modülün özgün ayar sayfasını sekme içinde güvenle render etmek için sarmalar.
 *
 * Üç ayrı tuzağı kapatır:
 *
 * 1. `Page.oninit` global `app.current` / `app.previous` durumunu kendine göre
 *    ezer. Sayfa sayfa içine gömülünce dış sayfanın yönlendirme durumu bozulur;
 *    süper init'ten sonra durumu geri koyuyoruz.
 *
 * 2. Gömülü sayfaya dış eklentinin kimliğini vermek zorundayız (yoksa
 *    `ExtensionPage.oninit` eklentiyi bulamayıp panoya yönlendirir). Ama sayfa
 *    içeride `this.extension.id` ile ayar ve izin arıyor; bunlar modülün kendi
 *    registry bağlamında kayıtlı. Bu yüzden init'ten sonra `this.extension`'ı
 *    kimliği modül bağlamı olan bir kopyayla değiştiriyoruz.
 *
 * 3. Bazı sayfalar (ör. reCAPTCHA) özelleştirmelerini `content()` yerine
 *    `sections()` içinde yapar. Bu yüzden `view` yalnızca `content()` değil,
 *    `sections()` çıktısının tamamını basar — izin ızgarası da buna dahildir.
 */
const embeddedCache = new Map();
function embedModulePage(PageClass, cacheKey) {
  const cached = embeddedCache.get(cacheKey);
  if (cached) return cached;
  class EmbeddedModulePage extends PageClass {
    // Page.oncreate/onremove bunu #app üzerinde ekleyip siliyor; gömülü
    // sayfanın dış sayfanın gövde sınıfıyla oynamasını istemiyoruz.
    bodyClass = '';
    oninit(vnode) {
      const current = app.current;
      const previous = app.previous;
      super.oninit(vnode);
      app.current = current;
      app.previous = previous;
      if (this.extension && vnode.attrs.contextId) {
        this.extension = {
          ...this.extension,
          id: vnode.attrs.contextId
        };
      }
    }
    view(vnode) {
      return this.sections(vnode).toArray();
    }
  }
  embeddedCache.set(cacheKey, EmbeddedModulePage);
  return EmbeddedModulePage;
}

/**
 * Framio konsolide ayar sayfası.
 *
 * Flarum bir eklenti için tek bir özel ayar sayfası slotu tutuyor
 * (AdminRegistry.registerPage → state.data[ext].page). Bir grupta birden çok
 * modül kendi sayfasını kaydedince son kaydeden diğerlerini eziyordu. Bu sayfa
 * her modülü kendi sekmesinde, kendi registry bağlamıyla gösterir.
 */
export default function framioGroupPage(allTabs) {
  return class FramioGroupPage extends ExtensionPage {
    activeTab = null;

    // Yalnızca gerçekten içeriği olan modüller sekme açar.
    tabs() {
      return allTabs.filter(t => app.registry.getPage(t.id) || app.registry.getSettings(t.id) || app.registry.extensionHasPermissions(t.id));
    }

    // Üst sınıf burada grup bağlamının izin ızgarasını basıyor; modüller kendi
    // bağlamlarını kullandığı için o bölüm hep boş kalırdı. İzinleri sekme
    // içinde, ait oldukları modülle birlikte gösteriyoruz.
    sections(vnode) {
      const items = new ItemList();
      items.add('content', this.content(vnode));
      return items;
    }
    content() {
      const tabs = this.tabs();
      if (!tabs.length) return null;
      const active = tabs.find(t => t.key === this.activeTab) || tabs[0];
      return m("div", {
        className: "FramioGroupPage"
      }, m("div", {
        className: "container"
      }, m("nav", {
        className: "FramioGroupPage-tabs",
        role: "tablist"
      }, tabs.map(tab => {
        const selected = tab.key === active.key;
        return m("button", {
          type: "button",
          role: "tab",
          "aria-selected": selected,
          className: 'FramioGroupPage-tab' + (selected ? ' FramioGroupPage-tab--active' : ''),
          onclick: () => {
            this.activeTab = tab.key;
          }
        }, tab.title);
      }))), m("div", {
        className: "FramioGroupPage-panel"
      }, [m("div", {
        className: "FramioGroupPage-tabPanel",
        key: active.key
      }, this.tabContent(active))]));
    }
    tabContent(tab) {
      const EmbeddedPage = app.registry.getPage(tab.id);
      if (EmbeddedPage) {
        const Embedded = embedModulePage(EmbeddedPage, tab.id);

        // Eski eklenti kimliğini sınıf olarak koruyoruz; modüllerin kendi
        // LESS kuralları `.fof-recaptcha-Page` gibi seçicilere dayanabiliyor.
        return m("div", {
          className: 'ExtensionPage FramioGroupPage-embedded ' + tab.legacyId + '-Page'
        }, m(Embedded, {
          id: this.extension.id,
          contextId: tab.id
        }));
      }
      const settings = app.registry.getSettings(tab.id);
      const hasPermissions = app.registry.extensionHasPermissions(tab.id);
      return [settings ? m("div", {
        className: "container"
      }, m(Form, null, settings.map(this.buildSettingComponent.bind(this)), m("div", {
        className: "Form-group Form-controls"
      }, this.submitButton()))) : m("div", {
        className: "container"
      }, m("h3", {
        className: "ExtensionPage-subHeader"
      }, app.translator.trans('core.admin.extension.no_settings'))), hasPermissions ? m("div", {
        className: "container FramioGroupPage-permissions"
      }, m("h2", {
        className: "ExtensionTitle"
      }, app.translator.trans('core.admin.extension.permissions_title')), m(ExtensionPermissionGrid, {
        extensionId: tab.id
      })) : null];
    }
  };
}